mapper.select:
SELECT COUNT(1)
FROM checklist
WHERE user_id = #{userId}
  AND list_date = #{date}

mapper.update:
UPDATE checklist
SET title = #{title},
    template_id = #{templateId},
    items = #{itemsJson},
    list_date = #{date},
    order_index = #{orderIndex},
    update_time = #{updateTime}
WHERE id = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM checklist
WHERE id = #{id}
  AND user_id = #{userId}
